'use strict';
const fs=require('fs'),crypto=require('crypto');
function dependencies(){return {db:require('./db').db,dispatcher:require('./dispatcher').dispatcher,broadcast:require('./ws').broadcast,managed:require('./spaceMedia').managed}}
function createProvider(get=dependencies){return async function provider(prompt,{signal,onProgress=()=>{}}={}){if(typeof prompt!=='string'||prompt.length>100000)throw Error('Ngữ cảnh lập trình quá lớn');const {db,dispatcher,broadcast,managed}=get(),jobId='code_text_'+crypto.randomUUID().replaceAll('-',''),batch='code_assistant_'+crypto.randomUUID();
 const stop=()=>{const row=db.prepare('SELECT status FROM jobs WHERE id=?').get(jobId);if(row?.status==='running')dispatcher.stopJob(jobId);else if(row?.status==='pending')db.prepare("UPDATE jobs SET status='stopped' WHERE id=?").run(jobId)};
 if(signal?.aborted)throw Error('Đã dừng yêu cầu');db.prepare("INSERT INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,batch_id,sort_order,created_at) VALUES(?,?,?,'text','pending',0,0,'1:1',0,0,5,?,0,datetime('now'))").run(jobId,prompt,'[]',batch);signal?.addEventListener('abort',stop,{once:true});if(!dispatcher.isRunning())dispatcher.start(broadcast);else dispatcher.trigger();const start=Date.now();try{for(;;){if(signal?.aborted)throw Error('Đã dừng yêu cầu');const job=db.prepare('SELECT status,error,video_url,elapsed_sec FROM jobs WHERE id=?').get(jobId);if(!job)throw Error('Không còn tác vụ MUSE');if(['failed','stopped'].includes(job.status))throw Error(job.error||'MUSE đã dừng');if(job.status==='completed'){const file=managed(job.video_url),st=fs.statSync(file);if(!st.isFile()||st.size>300000)throw Error('Kết quả lập trình MUSE không hợp lệ');return fs.readFileSync(file,'utf8')}onProgress(job.status==='pending'?'Đang chờ tài khoản MUSE rảnh':'MUSE đang viết code · '+(job.elapsed_sec||0)+' giây');if(Date.now()-start>7*60*1000){stop();throw Error('MUSE chưa trả lời sau 7 phút. Chưa sửa tệp nào.')}await new Promise(resolve=>{let timer;const done=()=>{clearTimeout(timer);signal?.removeEventListener('abort',done);resolve()};timer=setTimeout(done,1000);signal?.addEventListener('abort',done,{once:true})})}}finally{signal?.removeEventListener('abort',stop)}}}
function configured(){const {db}=dependencies();const rows=db.prepare('SELECT status,enabled FROM accounts WHERE credentials_encrypted IS NOT NULL').all();return {configured:rows.some(r=>r.enabled),online:rows.filter(r=>r.enabled&&r.status==='online').length}}
module.exports={createProvider,configured};
